/* ---------- API helpers ---------- */ /** Wraps a fetch with a hard timeout so the UI never hangs forever. */ function fetchWithTimeout(url, opts, ms) {
    return new Promise((resolve, reject)=>{
        const timer = setTimeout(()=>{
            reject(new Error(`Request timed out after ${ms}ms`));
        }, ms);
        fetch(url, opts).then((res)=>{
            clearTimeout(timer);
            resolve(res);
        }).catch((err)=>{
            clearTimeout(timer);
            reject(err);
        });
    });
}
async function searchOpenLibrary(q, signal) {
    const url = `https://openlibrary.org/search.json?q=${encodeURIComponent(q)}&limit=24&fields=key,title,author_name,first_publish_year,cover_i,edition_count`;
    const res = await fetchWithTimeout(url, {
        signal,
        headers: {
            Accept: "application/json"
        }
    }, 9000);
    if (!res.ok) throw new Error(`Open Library responded ${res.status}`);
    const data = await res.json();
    const docs = Array.isArray(data?.docs) ? data.docs : [];
    return docs.map((d)=>{
        const coverId = d.cover_i;
        return {
            id: String(d.key || `${d.title}-${d.first_publish_year || ""}`),
            title: d.title || "Untitled",
            author: Array.isArray(d.author_name) ? d.author_name[0] : d.author_name || "",
            year: d.first_publish_year ?? null,
            cover: coverId ? `https://covers.openlibrary.org/b/id/${coverId}-M.jpg` : undefined,
            link: d.key ? `https://openlibrary.org${d.key}` : "https://openlibrary.org",
            editions: d.edition_count
        };
    });
}
async function searchGoogleBooks(q, signal) {
    const url = `https://www.googleapis.com/books/v1/volumes?q=${encodeURIComponent(q)}&maxResults=24`;
    const res = await fetchWithTimeout(url, {
        signal
    }, 9000);
    if (!res.ok) throw new Error(`Google Books responded ${res.status}`);
    const data = await res.json();
    const items = Array.isArray(data?.items) ? data.items : [];
    return items.map((item)=>{
        const v = item.volumeInfo || {};
        const id = item.id || v.title || Math.random().toString(36);
        const cover = v.imageLinks?.extraLarge || v.imageLinks?.large || v.imageLinks?.medium || v.imageLinks?.thumbnail || v.imageLinks?.smallThumbnail;
        return {
            id: String(id),
            title: v.title || "Untitled",
            author: Array.isArray(v.authors) ? v.authors[0] : v.authors || "",
            year: v.publishedDate ? v.publishedDate.slice(0, 4) : null,
            cover: cover ? cover.replace(/^http:/, "https:") : undefined,
            link: v.infoLink || `https://books.google.com/books?id=${id}`,
            editions: undefined
        };
    });
}
